package com.example.jobplatform.service;
import com.example.jobplatform.dto.JobDtos.*; import com.example.jobplatform.entity.*; import com.example.jobplatform.repository.*; import com.fasterxml.jackson.databind.ObjectMapper; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class JobService {
 private final JobRepository jobs; private final OutboxRepository outbox; private final UserRepository users; private final ObjectMapper mapper; private final int maxAttempts;
 public JobService(JobRepository jobs,OutboxRepository outbox,UserRepository users,ObjectMapper mapper,@Value("${app.jobs.max-attempts}") int maxAttempts){this.jobs=jobs;this.outbox=outbox;this.users=users;this.mapper=mapper;this.maxAttempts=maxAttempts;}
 @Transactional public JobResponse submit(String email,SubmitJobRequest r){AppUser u=users.findByEmail(email).orElseThrow();Job j=new Job();j.setId(UUID.randomUUID());j.setOwnerId(u.getId());j.setJobType(r.jobType());j.setPayload(r.payload());j.setPriority(r.priority()==null?5:r.priority());j.setMaxAttempts(maxAttempts);jobs.save(j);OutboxEvent e=new OutboxEvent();e.setAggregateId(j.getId());e.setEventType("JOB_SUBMITTED");try{e.setPayload(mapper.writeValueAsString(new JobMessage(j.getId(),j.getPriority())));}catch(Exception ex){throw new IllegalStateException(ex);}outbox.save(e);return toResponse(j);}
 @Transactional(readOnly=true) public JobResponse get(String email,UUID id){AppUser u=users.findByEmail(email).orElseThrow();return jobs.findByIdAndOwnerId(id,u.getId()).map(this::toResponse).orElseThrow(()->new NoSuchElementException("Job not found"));}
 @Transactional(readOnly=true) public List<JobResponse> list(String email){AppUser u=users.findByEmail(email).orElseThrow();return jobs.findTop100ByOwnerIdOrderByCreatedAtDesc(u.getId()).stream().map(this::toResponse).toList();}
 @Transactional public JobResponse cancel(String email,UUID id){AppUser u=users.findByEmail(email).orElseThrow();Job j=jobs.findByIdAndOwnerId(id,u.getId()).orElseThrow(()->new NoSuchElementException("Job not found"));if(j.getStatus()==JobStatus.QUEUED||j.getStatus()==JobStatus.RETRYING){j.setStatus(JobStatus.CANCELLED);j.touch();}return toResponse(j);}
 public JobResponse toResponse(Job j){return new JobResponse(j.getId(),j.getJobType(),j.getStatus().name(),j.getPriority(),j.getAttempts(),j.getMaxAttempts(),j.getResult(),j.getErrorMessage(),j.getCreatedAt(),j.getStartedAt(),j.getCompletedAt());}
}
